  "unknownInput": "ignore",
  "input": {"sql": {"type": "string", "required": true}},
  "properties": {
    "id": {"type": "integer", "identifier": true},
    "info": {"type": "string"}
  }
}
EOF
cat > resources/fix.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`SELECT 1 AS id, (SELECT string_agg(id || ' cust=' || customer_id || ' total=' || total_cents || ' at=' || created_at, E'\n' ORDER BY id) FROM purchase) || E'\n--\n' || (SELECT string_agg(pl.purchase_id || ' book=' || pl.book_id || ' q=' || pl.quantity || ' up=' || pl.unit_price_cents, E'\n' ORDER BY pl.id) FROM purchase_line pl) || E'\n--\n' || (SELECT string_agg(id || ' price=' || price_cents || ' stock=' || stock || ' pub=' || published, E'\n' ORDER BY id) FROM book) || E'\n--\nseq=' || (SELECT last_value || ' called=' || is_called FROM purchase_id_seq) AS info`;
}
EOF
cat > resources/fix.command.ts <<'EOF'
export function create(input, ctx) {
  ctx.db.exec(ctx.sql`SELECT 1`);
  return 1;
}
EOF
